func maskTelegramBotToken(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	if strings.Contains(raw, "***") {
		return raw
	}
	if len(raw) <= 10 {
		return "bot***"
	}
	return raw[:6] + "***" + raw[len(raw)-4:]
}

